/// Returns a value within [min(a), max(a)].
/// q=0 -> min(a), q=100 -> max(a).
pub fn nanquantile(a: Vec<i8>, q: i8) -> i8 {
    // Per problem statement: a is non-empty and q in [0, 100].
    if q <= 0 {
        return get_min_val(&a);
    }
    if q >= 100 {
        return get_max_val(&a);
    }

    // Choose an order-statistic corresponding to the quantile.
    // Use a simple "nearest-rank" style: index = floor(q*(n-1)/100).
    let n = a.len();
    if n == 1 {
        return a[0];
    }

    let idx = ((q as i32) * ((n - 1) as i32) / 100) as usize;

    let mut sorted = a;
    sorted.sort(); // ascending
    sorted[idx]
}